const TAU = Math.PI * 2;
const INITIAL_YAW = -0.48;
const INITIAL_PITCH = -0.12;
const IDLE_VELOCITY = 0.085;
const PITCH_LIMIT = 1.25;

export function clamp(value, minimum, maximum) {
  return Math.max(minimum, Math.min(maximum, value));
}

export function createInitialState(reducedMotion = false) {
  return {
    yaw: INITIAL_YAW,
    pitch: INITIAL_PITCH,
    yawVelocity: reducedMotion ? 0 : IDLE_VELOCITY,
    pitchVelocity: 0,
    dragging: false,
    pointerId: null,
    x: 0,
    y: 0,
    time: 0,
  };
}

export function sampleLand(longitude, latitude) {
  let u = (longitude / TAU + 0.5) % 1;
  if (u < 0) u += 1;
  const v = clamp(0.5 - latitude / Math.PI, 0, 0.999999);
  const x = Math.floor(u * MASK.width);
  const y = Math.floor(v * MASK.height);
  return MASK.rows[y].charCodeAt(x) === 49;
}

export function applyKeyboardInput(state, key, reducedMotion = false) {
  const step = 0.13;
  if (key === 'ArrowLeft') state.yaw -= step;
  else if (key === 'ArrowRight') state.yaw += step;
  else if (key === 'ArrowUp') state.pitch = clamp(state.pitch + step, -PITCH_LIMIT, PITCH_LIMIT);
  else if (key === 'ArrowDown') state.pitch = clamp(state.pitch - step, -PITCH_LIMIT, PITCH_LIMIT);
  else if (key === 'Home') {
    state.yaw = INITIAL_YAW;
    state.pitch = INITIAL_PITCH;
    state.yawVelocity = reducedMotion ? 0 : IDLE_VELOCITY;
    state.pitchVelocity = 0;
  } else return false;
  return true;
}

export function stepMotion(state, deltaTime, reducedMotion = false) {
  if (state.dragging || reducedMotion) return;
  const dt = Math.min(Math.max(deltaTime, 0), 0.05);
  const ease = 1 - Math.exp(-1.35 * dt);
  state.yawVelocity += (IDLE_VELOCITY - state.yawVelocity) * ease;
  state.pitchVelocity *= Math.exp(-2.5 * dt);
  state.yaw = (state.yaw + state.yawVelocity * dt) % TAU;
  state.pitch = clamp(state.pitch + state.pitchVelocity * dt, -PITCH_LIMIT, PITCH_LIMIT);
}

export function applyPointerMovement(state, point, reducedMotion = false) {
  const deltaTime = Math.max((point.time - state.time) / 1000, 0.008);
  const deltaX = point.x - state.x;
  const deltaY = point.y - state.y;
  state.yaw -= deltaX * 0.009;
  state.pitch = clamp(state.pitch + deltaY * 0.008, -PITCH_LIMIT, PITCH_LIMIT);
  if (!reducedMotion) {
    state.yawVelocity = state.yawVelocity * 0.35 + (-deltaX * 0.009 / deltaTime) * 0.65;
    state.pitchVelocity = state.pitchVelocity * 0.35 + (deltaY * 0.008 / deltaTime) * 0.65;
  }
  state.x = point.x;
  state.y = point.y;
  state.time = point.time;
  return reducedMotion;
}

export function shouldAnimate(reducedMotion, pageVisible, intersecting) {
  return pageVisible && intersecting && !reducedMotion;
}

export function mountDadbotGlobe(root = document.querySelector('[data-dadbot-globe-root]')) {
  if (!root || root.dataset.globeMounted === 'true') return null;

  const canvas = root.querySelector('#dadbot-globe');
  const fallback = root.querySelector('.dadbot-globe-fallback');
  if (!canvas) return null;

  const context = canvas.getContext('2d');
  if (!context) return null;

  const motionQuery = matchMedia('(prefers-reduced-motion: reduce)');
  let reducedMotion = motionQuery.matches;
  const state = createInitialState(reducedMotion);
  const metrics = {
    frames: 0,
    renderTimeTotal: 0,
    renderTimeMax: 0,
    intervalTotal: 0,
    intervalSamples: 0,
    interactions: 0,
    resizeCount: 0,
  };
  let width = 0;
  let height = 0;
  let dpr = 1;
  let lastFrame = performance.now();
  let pageVisible = !document.hidden;
  let intersecting = true;
  let frameId = 0;
  const listenerController = new AbortController();
  const listenerSignal = listenerController.signal;

  function resize() {
    const rectangle = canvas.getBoundingClientRect();
    dpr = Math.min(devicePixelRatio || 1, 2);
    width = Math.max(280, Math.round(rectangle.width));
    height = Math.max(280, Math.round(rectangle.height));
    const pixelWidth = Math.round(width * dpr);
    const pixelHeight = Math.round(height * dpr);
    if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
      canvas.width = pixelWidth;
      canvas.height = pixelHeight;
      metrics.resizeCount += 1;
    }
    context.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function render() {
    const started = performance.now();
    context.clearRect(0, 0, width, height);
    const centerX = width / 2;
    const centerY = height * 0.515;
    const radius = Math.min(width * 0.37, height * 0.405);
    const cell = clamp(Math.round(radius / 29), 4, 9);
    const cosPitch = Math.cos(state.pitch);
    const sinPitch = Math.sin(state.pitch);
    const cosYaw = Math.cos(state.yaw);
    const sinYaw = Math.sin(state.yaw);
    const sun = { x: -0.38, y: 0.26, z: 0.89 };

    context.textAlign = 'center';
    context.textBaseline = 'middle';
    context.font = `${Math.max(6, cell * 1.08)}px 'Fira Code', Monaco, Consolas, 'Ubuntu Mono', monospace`;

    for (let pixelY = centerY - radius; pixelY <= centerY + radius; pixelY += cell) {
      const normalizedY = -(pixelY - centerY) / radius;
      for (let pixelX = centerX - radius; pixelX <= centerX + radius; pixelX += cell) {
        const normalizedX = (pixelX - centerX) / radius;
        const squaredRadius = normalizedX * normalizedX + normalizedY * normalizedY;
        if (squaredRadius > 1) continue;

        const normalizedZ = Math.sqrt(1 - squaredRadius);
        const orientedY = normalizedY * cosPitch + normalizedZ * sinPitch;
        const orientedZ = -normalizedY * sinPitch + normalizedZ * cosPitch;
        const orientedX = normalizedX * cosYaw + orientedZ * sinYaw;
        const finalZ = -normalizedX * sinYaw + orientedZ * cosYaw;
        const latitude = Math.asin(clamp(orientedY, -1, 1));
        const longitude = Math.atan2(orientedX, finalZ);
        const light = clamp((normalizedX * sun.x + normalizedY * sun.y + normalizedZ * sun.z + 0.32) / 1.32, 0, 1);
        const land = sampleLand(longitude, latitude);
        const characters = land ? '.:+oO%#' : '  ·..:';
        const alpha = land ? 0.44 + 0.48 * light : 0.12 + 0.30 * light;
        const index = clamp(Math.floor(light * (characters.length - 0.001)), 0, characters.length - 1);
        const character = characters[index];
        if (character === ' ') continue;

        context.fillStyle = land
          ? (light > 0.9 ? `rgba(226,255,230,${alpha})` : `rgba(140,255,151,${alpha})`)
          : `rgba(71,164,94,${alpha})`;
        context.fillText(character, pixelX, pixelY);
      }
    }

    const elapsed = performance.now() - started;
    metrics.frames += 1;
    metrics.renderTimeTotal += elapsed;
    metrics.renderTimeMax = Math.max(metrics.renderTimeMax, elapsed);
    metrics.averageRenderMs = metrics.renderTimeTotal / metrics.frames;
    metrics.averageFrameIntervalMs = metrics.intervalSamples ? metrics.intervalTotal / metrics.intervalSamples : 0;
    metrics.estimatedFps = metrics.averageFrameIntervalMs ? 1000 / metrics.averageFrameIntervalMs : 0;
    metrics.canvas = { cssWidth: width, cssHeight: height, pixelWidth: canvas.width, pixelHeight: canvas.height, dpr, cell, radius };
  }

  canvas.hidden = false;
  canvas.style.visibility = 'hidden';
  try {
    resize();
    render();
  } catch {
    canvas.hidden = true;
    canvas.style.removeProperty('visibility');
    return null;
  }
  canvas.style.removeProperty('visibility');
  if (fallback) fallback.hidden = true;
  root.dataset.globeMounted = 'true';

  function frame(now) {
    const deltaTime = Math.min((now - lastFrame) / 1000, 0.05);
    if (metrics.frames > 0) {
      metrics.intervalTotal += now - lastFrame;
      metrics.intervalSamples += 1;
    }
    lastFrame = now;
    if (shouldAnimate(reducedMotion, pageVisible, intersecting)) {
      stepMotion(state, deltaTime, reducedMotion);
      render();
    }
    frameId = requestAnimationFrame(frame);
  }

  function eventPoint(event) {
    return { x: event.clientX, y: event.clientY, time: performance.now() };
  }

  canvas.addEventListener('pointerdown', (event) => {
    state.dragging = true;
    state.pointerId = event.pointerId;
    canvas.setPointerCapture(event.pointerId);
    const point = eventPoint(event);
    state.x = point.x;
    state.y = point.y;
    state.time = point.time;
    state.yawVelocity = 0;
    state.pitchVelocity = 0;
    metrics.interactions += 1;
  }, { signal: listenerSignal });

  canvas.addEventListener('pointermove', (event) => {
    if (!state.dragging || event.pointerId !== state.pointerId) return;
    const point = eventPoint(event);
    if (applyPointerMovement(state, point, reducedMotion)) render();
  }, { signal: listenerSignal });

  function releasePointer(event) {
    if (event.pointerId !== state.pointerId) return;
    state.dragging = false;
    state.pointerId = null;
  }

  canvas.addEventListener('pointerup', releasePointer, { signal: listenerSignal });
  canvas.addEventListener('pointercancel', releasePointer, { signal: listenerSignal });
  canvas.addEventListener('lostpointercapture', () => {
    state.dragging = false;
    state.pointerId = null;
  }, { signal: listenerSignal });

  canvas.addEventListener('keydown', (event) => {
    if (!applyKeyboardInput(state, event.key, reducedMotion)) return;
    event.preventDefault();
    metrics.interactions += 1;
    if (reducedMotion) render();
  }, { signal: listenerSignal });

  function handleMotionPreference(event) {
    reducedMotion = event.matches;
    if (reducedMotion) {
      state.yawVelocity = 0;
      state.pitchVelocity = 0;
      render();
    } else if (!state.dragging) {
      state.yawVelocity = IDLE_VELOCITY;
    }
  }
  motionQuery.addEventListener?.('change', handleMotionPreference, { signal: listenerSignal });

  let resizeObserver = null;
  if ('ResizeObserver' in window) {
    resizeObserver = new ResizeObserver(() => { resize(); render(); });
    resizeObserver.observe(canvas);
  } else {
    window.addEventListener('resize', resize, { signal: listenerSignal });
  }

  let intersectionObserver = null;
  if ('IntersectionObserver' in window) {
    intersectionObserver = new IntersectionObserver((entries) => {
      intersecting = entries[0]?.isIntersecting ?? false;
      if (pageVisible && intersecting) lastFrame = performance.now();
    }, { threshold: 0.01 });
    intersectionObserver.observe(canvas);
  }

  document.addEventListener('visibilitychange', () => {
    pageVisible = !document.hidden;
    if (pageVisible && intersecting) lastFrame = performance.now();
  }, { signal: listenerSignal });

  frameId = requestAnimationFrame(frame);

  return {
    state,
    metrics,
    render,
    destroy() {
      cancelAnimationFrame(frameId);
      listenerController.abort();
      resizeObserver?.disconnect();
      intersectionObserver?.disconnect();
      canvas.hidden = true;
      if (fallback) fallback.hidden = false;
      delete root.dataset.globeMounted;
    },
  };
}

function autoMount() {
  mountDadbotGlobe();
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', autoMount, { once: true });
  else autoMount();
}
